// Regex reduz exposicao; nao garante anonimizacao. Sem logs ou copia do payload.
const invalidInput = () => { throw new Error('Entrada invalida para sanitizacao.'); };
const items = $input.all();
if (!items.length) invalidInput();

return items.map((item, index) => {
  const body = item.json?.body;
  if (!body || typeof body !== 'object' || Array.isArray(body) ||
      typeof body.review_text !== 'string' || body.review_text.length > 20000) {
    invalidInput();
  }
  let text = body.review_text.normalize('NFKC').replace(/[\u200B-\u200D\uFEFF]/g, '');
  if (!text.trim()) invalidInput();

  // URLs completas antes de e-mails; dominios sem protocolo depois dos e-mails.
  // Mantem pontuacao final da frase fora do marcador.
  const maskUrl = (match) => {
    const punctuation = match.match(/[.,;:!?)}\]]+$/)?.[0] || '';
    return '[URL]' + punctuation;
  };
  text = text.replace(/\b(?:https?:\/\/|ftp:\/\/|www\.)[^\s<>"']+/gi, maskUrl);
  text = text.replace(/(?<![\p{L}\p{N}_.+%-])[\p{L}\p{N}_.+%-]+@[\p{L}\p{N}-]+(?:\.[\p{L}\p{N}-]+)+/gu, '[EMAIL]');
  text = text.replace(/(?<![\p{L}\p{N}])\d{2}\s*[.]?\s*\d{3}\s*[.]?\s*\d{3}\s*[\/]?\s*\d{4}\s*[-]?\s*\d{2}(?![\p{L}\p{N}])/gu, '[CNPJ]');
  text = text.replace(/(?<![\p{L}\p{N}])[a-z\d]{2}\.[a-z\d]{3}\.[a-z\d]{3}\/[a-z\d]{4}-\d{2}(?![\p{L}\p{N}])/giu, '[CNPJ]');
  text = text.replace(/(?<![\p{L}\p{N}])[a-z\d]{12}\d{2}(?![\p{L}\p{N}])/giu, '[CNPJ]');
  text = text.replace(/(?<![\p{L}\p{N}_@])[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?(?:\.[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?)*\.[a-z]{2,63}(?::\d{2,5})?(?:[/?#][^\s<>"']*)?(?![\p{L}\p{N}_@])/giu, maskUrl);

  text = text.replace(/(?<![\p{L}\p{N}])0[358]00[\s.-]?\d{3}[\s.-]?\d{4}(?![\p{L}\p{N}])/gu, '[TELEFONE]');
  // CPF antes dos demais telefones/CEP; numeros de 11 digitos sao ambiguos.
  // Nao verifica digitos verificadores: sequencias sinteticas tambem sao mascaradas.
  text = text.replace(/(?<![\p{L}\p{N}])\d{3}\s*[.]?\s*\d{3}\s*[.]?\s*\d{3}\s*[-]?\s*\d{2}(?![\p{L}\p{N}])/gu, '[CPF]');
  text = text.replace(/(?<![\p{L}\p{N}])(?:\+?55[\s.-]?)?(?:\(\s*\d{2}\s*\)[\s.-]?|\d{2}[\s.-]?)(?:\d[\s.-]?)?\d{4}[\s.-]?\d{4}(?![\p{L}\p{N}])/gu, '[TELEFONE]');
  // Sem DDD: exige separador ou rotulo para reduzir colisao com numeros comuns.
  text = text.replace(/(?<![\p{L}\p{N}])\d{4,5}[ .-]\d{4}(?![\p{L}\p{N}])/gu, '[TELEFONE]');
  text = text.replace(/\b(tel(?:efone)?|cel(?:ular)?|whats(?:app)?)\s*[:=]?\s*(\d{8,9})(?!\d)/gi, '$1: [TELEFONE]');
  text = text.replace(/(?<![\p{L}\p{N}])\d{5}[-.\s]?\d{3}(?![\p{L}\p{N}])/gu, '[CEP]');

  return { json: { review_text_sanitized: text }, pairedItem: { item: index } };
});

// O original e retomado apenas para a tratativa no Airtable, nunca para o LLM.
const raw = $json?.choices?.[0]?.message?.content;
if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('Resposta do LLM ausente ou invalida.');
}
let parsed;
try { parsed = JSON.parse(raw); }
catch { throw new Error('Resposta do LLM nao e JSON valido.'); }
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed) ||
    typeof parsed.sentiment !== 'string' || typeof parsed.theme !== 'string') {
  throw new Error('Classificacao do LLM invalida.');
}
const sentiment = parsed.sentiment.toLowerCase().trim();
const theme = parsed.theme.toLowerCase().trim();
if (!['positivo', 'neutro', 'negativo'].includes(sentiment) ||
    !['entrega', 'produto', 'atendimento', 'preco', 'app_bug'].includes(theme)) {
  throw new Error('Classificacao do LLM fora dos valores permitidos.');
}
const webhook = $('Webhook Review').first().json.body;
return [{ json: {
  review_id: webhook.review_id,
  customer_name: webhook.customer_name,
  source: webhook.source,
  rating: webhook.rating,
  review_text: webhook.review_text,
  sentiment,
  theme,
  processed_at: new Date().toISOString()
} }];

